package embed

import (
	"context"
	"hash/fnv"
	"math"
	"strings"
	"unicode"
)

// DefaultLexicalDims 為離線備援向量的維度；中文二字詞雜湊在 1024 維下碰撞率可接受。
const DefaultLexicalDims = 1024

// NewLexical 回傳離線的字元 unigram + bigram 雜湊向量函式（L2 正規化）。
// 它只反映字面重疊，不具語意理解，僅作為測試與無模型環境的備援。
//
// @ai:generated by=claude-fable-5-1 date=2026-10-09
// @ai:purpose 讓 contract test 與 CI 不需外部 API 也能跑完整 ingest/search 流程
// @ai:input dims 向量維度
// @ai:output 向量化函式
// @ai:sideeffect none
func NewLexical(dims int) Func {
	if dims <= 0 {
		dims = DefaultLexicalDims
	}
	return func(_ context.Context, text string) ([]float32, error) {
		vec := make([]float32, dims)
		runes := make([]rune, 0, len(text))
		for _, r := range strings.ToLower(text) {
			if unicode.IsLetter(r) || unicode.IsDigit(r) {
				runes = append(runes, r)
			}
		}
		add := func(s string) {
			h := fnv.New32a()
			h.Write([]byte(s))
			vec[int(h.Sum32()%uint32(dims))]++
		}
		for i, r := range runes {
			add(string(r))
			if i+1 < len(runes) {
				add(string(runes[i : i+2]))
			}
		}
		var norm float64
		for _, v := range vec {
			norm += float64(v) * float64(v)
		}
		if norm == 0 {
			vec[0] = 1
			return vec, nil
		}
		n := float32(math.Sqrt(norm))
		for i := range vec {
			vec[i] /= n
		}
		return vec, nil
	}
}
